/**
 * Muxes a finished voiceover onto a rendered video.
 *
 * Use this when the audio already exists as one file, for example generated by
 * hand in the ElevenLabs UI. For per line synthesis from a timed script, use
 * scripts-voiceover.mjs instead.
 *
 * It refuses to guess: if the audio and video lengths differ by more than a
 * small tolerance it says so and stops, because silently padding or truncating
 * is how a video ends up with the last line clipped. Re-time the video from
 * the audio first (scripts-audio-timeline.mjs), then come back here.
 *
 *   node scripts-attach-audio.mjs <video> <audio> [--out file] [--music bed.mp3]
 *                                 [--gain 1.0] [--force]
 */
import {execFileSync, spawnSync} from 'child_process';
import {existsSync} from 'fs';

const args = process.argv.slice(2);
const positional = args.filter((a) => !a.startsWith('--'));
const [video, audio] = positional;
const opt = (n, d) => {
  const i = args.indexOf(`--${n}`);
  return i > -1 ? args[i + 1] : d;
};
const force = args.includes('--force');
const music = opt('music', null);
const gain = Number(opt('gain', '1.0'));
/**
 * Seconds of silence before the voice starts.
 *
 * For a video that opens on a beat with no spoken line, a silent visual hook,
 * the recording has to be pushed back by exactly that beat's length. Every
 * line then lands on the scene built for it and the opening plays without
 * narration, which is what it was designed to do.
 */
const delay = Number(opt('delay', '0'));

if (!video || !audio || !existsSync(video) || !existsSync(audio)) {
  console.error('usage: node scripts-attach-audio.mjs <video.mp4> <voice.mp3> [--out out.mp4]');
  console.error('       both files must exist.');
  process.exit(2);
}

const dur = (f) =>
  Number(
    execFileSync('ffprobe', [
      '-v', 'error',
      '-show_entries', 'format=duration',
      '-of', 'default=noprint_wrappers=1:nokey=1',
      f,
    ], {encoding: 'utf8'}).trim(),
  );

const v = dur(video);
const a = dur(audio);
const out = opt('out', video.replace(/\.mp4$/, '-voiced.mp4'));

console.log(`  video  ${v.toFixed(2)}s  ${video}`);
console.log(`  audio  ${a.toFixed(2)}s  ${audio}`);
if (delay) console.log(`  delay  ${delay.toFixed(2)}s of silence first, so the voice ends at ${(a + delay).toFixed(2)}s`);

const drift = Math.abs(v - (a + delay));
const TOL = 0.5;
if (drift > TOL && !force) {
  console.error(
    `\n  STOP: they differ by ${drift.toFixed(2)}s.\n` +
      `  ${a < v ? 'The audio is shorter, so the video would run on in silence.' : 'The audio is longer, so the last line would be cut off.'}\n\n` +
      `  Re-time the video from the audio, which is the fix that keeps them locked:\n` +
      `    node scripts-audio-timeline.mjs ${audio} --lines <N> --out <timeline.ts>\n` +
      `  then point a Reel at that timeline and re-render.\n\n` +
      `  Or pass --force to mux anyway and accept the mismatch.`,
  );
  process.exit(1);
}

const inputs = ['-i', video, '-i', audio];
/**
 * Pad the voice out to the video length instead of using -shortest.
 *
 * -shortest truncates to whichever stream is shorter, which threw away the
 * tail hold the timeline deliberately adds after the last word. The video is
 * authoritative for length here; the audio just needs silence on the end.
 */
const filters = [
  `[1:a]volume=${gain},adelay=${Math.round(delay * 1000)}:all=1,apad,atrim=0:${v.toFixed(3)}[voice]`,
];
let mix = '[voice]';
if (music) {
  if (!existsSync(music)) throw new Error(`music not found: ${music}`);
  inputs.push('-i', music);
  filters.push(`[2:a]volume=0.12,afade=t=out:st=${Math.max(0, v - 1.2).toFixed(2)}:d=1.2[bed]`);
  filters.push(`[voice][bed]amix=inputs=2:normalize=0:dropout_transition=0[m]`);
  mix = '[m]';
}
filters.push(`${mix}alimiter=limit=0.95,aresample=44100[aout]`);

const r = spawnSync('ffmpeg', [
  '-y', '-v', 'error',
  ...inputs,
  '-filter_complex', filters.join(';'),
  '-map', '0:v',
  '-map', '[aout]',
  '-c:v', 'copy',
  '-c:a', 'aac',
  '-b:a', '192k',
  out,
], {encoding: 'utf8'});

if (r.status !== 0) {
  console.error(r.stderr);
  process.exit(1);
}
console.log(`\n  wrote ${out}  (${dur(out).toFixed(2)}s)`);
